/* DOM-free model, shared by the forwarder UI, reports and read-only tool. */
(function(){'use strict';
const d=window.VersionCompassForwarderData;
const labels={available:'Available',conditional:'Conditional',unavailable:'Unavailable',not_established:'Not established',conflicting:'Conflicting evidence'};
const defaults={type:'uf',from:'9.4',to:'10.4',destination:'cmp',receiver:'10.4',os:'unspecified',arch:'unspecified',provider:'unspecified',region:'unspecified',topology:'direct'};
const options={type:['uf','hf'],from:d.releases,to:d.releases,destination:['cmp','cloud','fr-m','fr-h'],receiver:['unspecified','9.3','9.4','10.0','10.1','10.2','10.3','10.4','10.5'],os:['unspecified',...new Set(d.osRows.map(r=>r[0])),'other'],arch:['unspecified','x86_64','arm64','other'],provider:['unspecified','aws','azure','gcp'],topology:['direct','intermediate','edge']};
function read(search){const p=new URLSearchParams(search),s={...defaults},errors=[];for(const k of Object.keys(defaults)){if(!p.has(k))continue;const v=p.get(k);if(p.getAll(k).length!==1)errors.push('Repeated '+k+' selection.');if(k==='region'){if(!/^[a-z0-9-]{1,50}$/.test(v))errors.push('Invalid region.');else s[k]=v;}else if(!options[k].includes(v))errors.push('Unrecognized '+k+': '+v);else s[k]=v;}if(p.getAll('product').length>1)errors.push('Repeated product selection.');return {state:s,errors};}
function url(s){const p=new URLSearchParams({product:'forwarders'});for(const k of Object.keys(defaults))p.set(k,s[k]);return '?'+p;}
function claim(title,status,detail,source){return {title,status,detail,source,reviewed:source?d.sources[source]?.reviewed:null};}
function renewal(s){let status='conditional';if(s.destination!=='cloud'||s.topology!=='direct'||d.excludedRenewalRegions.includes(s.region)||['azure','gcp'].includes(s.provider))status='unavailable';return claim('Automatic Cloud certificate renewal',status,'UF / HF 9.3.0+; Cloud 9.2.2406+; commercial AWS only; direct output, not an intermediate forwarder or Edge Processor. Excludes '+d.excludedRenewalRegions.join(', ')+'. Enable autoCertRotation explicitly; one eligible Cloud output group. Confirm exact stack and region before enabling.','renewal');}
function assess(s){
 const errors=[];for(const k of Object.keys(options))if(!options[k].includes(s[k]))errors.push('Invalid '+k);if(!/^[a-z0-9-]{1,50}$/.test(s.region||''))errors.push('Invalid region');
 if(d.releases.indexOf(s.from)>=d.releases.indexOf(s.to))errors.push('Select a target after the current release. Same-line patch planning is not modeled; consult the exact patch notes.');
 if(errors.length)return {errors};
 const enterprise=window.SPLUNK_DATA.enterprise;
 const engine=window.VersionCompassComparison.create(window.SPLUNK_DATA,{product:'platform',platform:'enterprise',from:s.from,to:s.to});
 const path=s.type==='hf'?engine.selectedPath():engine.shortestPath(s.from,s.to,d.ufEdges);
 const steps=path.slice(1).map((to,i)=>({from:path[i],to,source:s.type==='hf'?'enterprise':{'10.0':'upgrade100','10.2':'upgrade102','10.4':'upgrade104'}[to]}));
 const route=claim('Upgrade support',path.length?'conditional':'not_established',path.length?'Documented release-line path: '+path.join(' → ')+'. Use a suitable supported maintenance release at each step; this is not a patch or OS approval.':'No documented path is recorded for this selection.',s.type==='hf'?'enterprise':'upgrade104');
 let receiver;
 if(s.destination==='cmp')receiver=claim('Receiver compatibility',s.topology==='edge'||!['9.3','9.4','10.0','10.2','10.4'].includes(s.receiver)?'not_established':'available',s.topology==='edge'?'The separate Edge Processor pairing has not been established for this selection.':'The CMP matrix records events, metrics and HTTPS forwarding for the selected lines when listed. It includes direct and intermediate forwarding. Prefer receiver versions at least as new as the forwarder; compatibility does not establish support lifecycle.','receiver');
 else {const allowed=['10.2','10.4'].includes(s.to)?['10.1','10.2','10.3','10.4','10.5']:['9.3','10.0','10.1','10.2','10.3','10.5'];receiver=claim('Receiver compatibility',s.destination==='cloud'&&s.topology==='direct'&&allowed.includes(s.receiver)?'conditional':'not_established','Cloud service-details pairing applies to the forwarder directly connected to the stack. For an intermediate tier, assess that tier separately. FR-M / FR-H stack-specific pairing and authorization are not established by the commercial table.','cloud');}
 const authorization=claim('Authorization', 'not_established',s.destination==='cmp'?'CMP means customer-managed Splunk Enterprise on premises or in a customer-managed cloud. No authorization determination is made for that deployment.':'Confirm the exact '+s.destination.toUpperCase()+' offering boundary, region, feature and entitlement. Receiver compatibility and FIPS configuration do not establish FedRAMP authorization.',null);
 const osRow=d.osRows.find(r=>r[0]===s.os&&r[1]===s.arch);
 const os=claim('Target OS / architecture',s.to==='10.4'&&osRow?osRow[s.type==='uf'?2:3]:'not_established',s.to==='10.4'&&osRow?(s.os==='Windows 11'&&s.type==='uf'?'UF 10.4.0 on Windows 11 ARM uses Prism x64 emulation on a best-efforts basis; not certified. Event Log and kernel-driver inputs and performance have unsupported or unvalidated scope.':'10.4 package matrix: '+s.os+' / '+s.arch+'. Check vendor lifecycle and required input support separately.'):'Exact package support is not recorded for this selection. The curated matrix covers selected 10.4 platforms only; check the target-version OS table.','os');
 const technical=s.type==='hf'?engine.selectedTechnicalChanges().filter(r=>d.hfComponents.includes(r.component)&&(!/Windows/.test(r.component)||s.os.startsWith('Windows')||s.os==='unspecified')&&(!/Unix/.test(r.component)||!s.os.startsWith('Windows'))):[];
 const targetRuntime=s.type==='hf'?Object.entries(enterprise.releasesData).filter(([v])=>d.releases.includes(v)&&d.releases.indexOf(v)<=d.releases.indexOf(s.to)).flatMap(([v,r])=>(r.technicalChanges||[]).filter(t=>/Python|Node.js/.test(t.component)).map(t=>({...t,release:v}))).sort((a,b)=>d.releases.indexOf(a.release)-d.releases.indexOf(b.release)):[];
 const risks=[];if(s.to==='10.4')risks.push(claim('Avoid Enterprise 10.4.2 in the forwarding chain','conditional','10.4.2 can stall acknowledged forwarding with useACK=true on a receiving Heavy Forwarder or indexer. Splunk recommends 10.4.3 or later. Check receivers as well as the selected forwarder.','ack'));
 if(os.status==='unavailable')risks.push(os);
 const security=claim(s.type==='uf'?'UF security patch floors · SVD-2026-0404':'HF / Enterprise security patch floors · SVD-2026-0505','conditional',s.type==='uf'?'CVE-2026-22796 fixes: 9.4.10, 10.0.4 and 10.2.1 on their respective lines. These are advisory-specific floors, not current-patch recommendations or a complete vulnerability assessment.':'Selected package fixes: 9.4.11, 10.0.6 and 10.2.3 on their respective lines. Apply component-specific advisory footnotes; these are not universal safe-patch guarantees.',s.type==='uf'?'ufSecurity':'hfSecurity');
 return {errors,scope:{...s},path,steps,claims:[route,receiver,authorization],os,features:[renewal(s)],technical,targetRuntime,risks,security,requiredChecks:['Validate exact patch and OS at every upgrade step.','Back up configuration and input checkpoints; rehearse recovery and validate event delivery, duplication, latency and acknowledgements.','Check each deployed add-on and premium-app integration against its own runtime and exact platform / app patch matrix. No premium-app pairing is inferred from forwarder compatibility.','Confirm credentials, trust chains, receiver endpoints and network connectivity for the complete forwarding chain.'],coverage:'Selected 9.4–10.4 release lines and source-backed highlights. Historical coverage, patch issues and OS coverage are not exhaustive.'};
}
window.VersionCompassForwarders={defaults,options,labels,read,url,assess,renewal};
}());
